import hashlib,json,math,signal,time,traceback
from pathlib import Path
from rmuc2027_core.engine import Match,binary_path
from rmuc2027_research.rl.scenarios import ScenarioSpec
from rmuc2027_research.rl.warp_kinematic import batching
p=Path(__file__).resolve().parent
paths=[Path('packages/core/rmuc2027_core/engine.py'),Path(binary_path())]+[Path('research/rmuc2027_research/rl/warp_kinematic')/n for n in ('arena.py','batching.py','dynamics.py')]
def sources():return {str(q):hashlib.sha256(q.read_bytes()).hexdigest() for q in paths}
start=time.time();out={'started_unix':start,'max_wall_seconds':60,'training_updates':0,'cases':[],'source_sha256':sources(),'passed':False}
def interrupted(*args):raise TimeoutError('External probe deadline')
signal.signal(signal.SIGTERM,interrupted)
class Recorder:
 protocol='kinematic_frame'
 def __init__(self):self.inner=batching.BatchClient(service,'cuda:0');self.requests=[]
 def step_encoded(self,r):
  result=self.inner.step_encoded(r)
  self.requests.append({'sequence':r['sequence'],'version':r['version'],'sentries':[{k:b.get(k) for k in ('id','model','jump','enabled','grounded','transform')} for b in r['robots'] if b['role']=='sentry'],'strengths':{b['id']:float(self.inner.state[i,18]) for i,b in enumerate(r['robots']) if b['role']=='sentry'}})
  return result
 def close(self):self.inner.close()
service=batching.PhysicsService(1)
try:
 for label,red,blue in [('A',2772,2772),('B',2771,2773),('C-reset',2772,2772)]:
  if time.time()-start>49:raise TimeoutError('Internal probe deadline')
  roster=ScenarioSpec((303,303),(303,303)).lineups();roster['red']['7']=red;roster['blue']['7']=blue
  lineups={t:[{'slot':int(k),'model':v} for k,v in values.items()] for t,values in roster.items()}
  adapter=Recorder();row={'case':label,'red_model':red,'blue_model':blue,'frames':0,'invalid_events':[],'finite':True}
  out['cases'].append(row)
  with Match(seed=42,duration=10,lineups=lineups,physics_adapter=adapter,battle_settings={'drones_enabled':False,'timed_assembly':True}) as match:
   def step(cmd):
    f=match.step(cmd);row['frames']+=1
    robots={r['team']:r for r in f['robots'] if r['slot']==7}
    for r in robots.values():
     assert all(math.isfinite(r[k]) for k in ('x','y','z','vx','vy','vz'))
     assert all(math.isfinite(v) for v in r['quaternion'])
    row['invalid_events'] += [e for e in f.get('events',[]) if e.get('type')=='invalid_action']
    return robots
   for _ in range(10):robots=step({})
   row['grounded_before']={t:r['grounded'] for t,r in robots.items()}
   initial={t:r['z'] for t,r in robots.items()};peaks={t:0. for t in robots};speeds={t:0. for t in robots}
   if red==2772:
    for tick in range(10):
     robots=step({t:{'7':{'move':[0.,0.],'jump':s if tick==0 else 0.}} for t,s in [('red',.2),('blue',.8)]})
     for t,r in robots.items():peaks[t]=max(peaks[t],r['z']-initial[t]);speeds[t]=max(speeds[t],r['vz'])
    row.update(peak_height_delta_m=peaks,peak_upward_speed_mps=speeds)
    assert speeds['blue']>speeds['red']>0.,'actual jump strength did not produce ordered upward velocities'
    assert peaks['blue']>peaks['red']>0.,'actual jump strength did not produce ordered heights'
    assert all(value==0. for value in adapter.requests[0]['strengths'].values()),'new client inherited old jump strength'
    pushed=next(r for r in adapter.requests if r['sequence']==10)
    assert abs(pushed['strengths']['red-7']-.2)<1e-6 and abs(pushed['strengths']['blue-7']-.8)<1e-6
   else:
    for _ in range(20):robots=step({'red':{'7':{'move':[.05,0.]}},'blue':{'7':{'move':[-.05,0.],'transform':True}}})
    row['fold_progress']={t:r['transform_progress'] for t,r in robots.items()}
    row['fold_duration_checked_s']=1.
   assert not row['invalid_events']
  row['requests']=adapter.requests;row['completed']=True
 out['passed']=True
except BaseException as e:out.update(error=type(e).__name__+': '+str(e),traceback=traceback.format_exc())
finally:
 service.close();out.update(wall_seconds=time.time()-start,source_unchanged=sources()==out['source_sha256'],service_thread_stopped=not service.thread.is_alive(),cleanup_errors=service.cleanup_errors)
 (p/'warp-match-result.json').write_text(json.dumps(out,indent=2,allow_nan=False)+'\n');print(json.dumps({k:v for k,v in out.items() if k!='cases'}))
raise SystemExit(0 if out['passed'] else 1)

