def hashes():return {p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in SOURCE_FILES}
def save(path,value):
    temp=path.with_suffix(path.suffix+'.tmp');temp.write_text(json.dumps(value,indent=2,allow_nan=False)+'\n');temp.replace(path)
def worker():
    start=time.time();deadline=float(os.environ['MJ_PROBE_DEADLINE'])
    out={'started_unix':start,'pid':os.getpid(),'deadline_unix':deadline,'training_updates':0,'actor_samples':0,'cases':[],'source_sha256':hashes(),'status':'running'}
    result_path=HERE/'result.json';save(result_path,out)
    def interrupt(*args):raise TimeoutError('Probe supervisor deadline')
    signal.signal(signal.SIGTERM,interrupt)
    from rmuc2027_core.engine import Match
    from rmuc2027_research.rl.scenarios import ScenarioSpec
    from rmuc2027_research.rl.mjwarp.arena import ArenaPhysics
    from rmuc2027_research.rl.mjwarp import batching
    import numpy as np
    service=batching.PhysicsService(1);batching.active_service=service
    process_exits=[]
    class Recorder(ArenaPhysics):
        def __init__(self,row):
            super().__init__('cuda:0');self.row=row;self.targets={};self.body_map={};self.steps=0
        def step(self,request):
            if not self.body_map:
                for robot,position in self.targets.items():
                    candidates=[(math.dist(b['pose']['pos'],position),b['id']) for b in request['bodies'] if b['dynamic']]
                    distance,identifier=min(candidates)
                    if distance>1e-5:raise RuntimeError('Cannot match initial native body origin: '+robot)
                    self.body_map[robot]=identifier
                if len(set(self.body_map.values()))!=len(self.body_map):raise RuntimeError('Ambiguous robot/body map')
                self.row['body_ids']=self.body_map
            begin=time.time();result=super().step(request);self.steps+=1
