class UnprintableCleanupError(RuntimeError):
    def __str__(self):
        raise RuntimeError('cleanup exception formatting failed')

class BrokenNotePrimaryError(ValueError):
    def add_note(self, note):
        raise RuntimeError('primary note hook failed')

class CatchingAdapter(Adapter):
    def step(self, request):
        self.active = True
        try:
            try:
                self.match.close()
            except RuntimeError as error:
                assert 'active physics callback' in str(error)
                assert not self.match.closed and self.close_calls == 0
            else:
                raise AssertionError('reentrant close was accepted')
            return {'op': 'external_physics_result'}
        finally:
            self.active = False
    def step_encoded(self, request):
        self.step(request)
        return b'{"op":"kinematic_frame_result"}\n'

