def thread_id(path):
    if not path.exists():
        return None
    with path.open() as stream:
        for line in stream:
            try:
                value = json.loads(line)
            except ValueError:
                continue
            if value.get('type') == 'thread.started':
                return value.get('thread_id')
    return None


def launch(name, prompt_path, turn=0, previous_thread=None):
    refresh_deadline()
    if time.time() >= DEADLINE - 120:
        return False
    folder = BASE / name
    folder.mkdir(exist_ok=True)
    events = folder / f'events-{turn:03d}.jsonl'
    stderr = folder / f'stderr-{turn:03d}.log'
    result = folder / f'result-{turn:03d}.md'
    if events.exists():
        raise RuntimeError('Refusing to overwrite an existing worker turn: ' + str(events))
    command = PREFIX + (['resume', previous_thread] if previous_thread else [])
    command += ['--json', '--output-last-message', str(result), '-']
    with prompt_path.open('rb') as source, events.open('xb') as out, stderr.open('xb') as err:
        process = subprocess.Popen(command, cwd=ROOT, stdin=source, stdout=out, stderr=err,
                                   start_new_session=True,
                                   env={**os.environ, 'OMP_NUM_THREADS': '1',
                                        'OPENBLAS_NUM_THREADS': '1', 'MKL_NUM_THREADS': '1'})
    record = dict(name=name, pid=process.pid, pgid=process.pid, turn=turn,
                  state='running', start_unix=time.time(), deadline_unix=DEADLINE,
                  thread_id=previous_thread, command=command,
                  events=str(events), stderr=str(stderr), result=str(result),
                  model='gpt-6-astra', reasoning_effort='ultra', requested_service_tier='ultrafast')
    jobs[name] = (process, record)
    write(folder / 'status.json', record)
    return True


def snapshot():
    write(BASE / 'sessions.json', {'deadline_unix': DEADLINE,
          'updated_unix': time.time(), 'sessions': [r for _, r in jobs.values()]})


def stop_owned():
    active = [(p, r) for p, r in jobs.values() if p.poll() is None]
    for sig, grace in ((signal.SIGINT, 8), (signal.SIGTERM, 5), (signal.SIGKILL, 1)):
        for process, record in active:
            if process.poll() is None:
                try:
                    os.killpg(process.pid, sig)
                except ProcessLookupError:
                    pass
                record['stop_signal'] = sig.name
        until = time.monotonic() + grace
        while time.monotonic() < until and any(p.poll() is None for p, _ in active):
            time.sleep(.2)
    for process, record in active:
        record.update(state='stopped_at_budget', exit_code=process.poll(), end_unix=time.time())
        write(BASE / record['name'] / 'status.json', record)


def main():
    (BASE / 'runner.pid').write_text(str(os.getpid()) + '\n')
    try:
        previous = BASE / 'sessions.json'
        if previous.exists():
            for record in json.loads(previous.read_text())['sessions']:
                if record['state'] != 'completed' or record.get('exit_code') is None:
                    raise RuntimeError('Only restart the controller at a completed-turn boundary')
                jobs[record['name']] = (FinishedProcess(record), record)
        else:
            for role in ('physics', 'transport', 'web_server'):
                launch(role, BASE / role / 'task.md')
            for role in ('physics', 'transport', 'web_server'):
                name = 'supervisor_' + role
                launch(name, BASE / name / 'task.md')
        snapshot()
        while True:
            refresh_deadline()
            if time.time() >= DEADLINE:
                break
            for name, (process, record) in list(jobs.items()):
                if not record['thread_id']:
                    record['thread_id'] = thread_id(Path(record['events']))
                code = process.poll()
                if code is not None and record['state'] == 'running':
                    record.update(state='completed' if code == 0 else 'failed',
                                  exit_code=code, end_unix=time.time())
                write(BASE / name / 'status.json', record)
                if code is not None and time.time() < DEADLINE - 120:
                    queue = BASE / name / 'followups'
                    pending = sorted(queue.glob('*.json')) if queue.exists() else []
                    if pending:
                        request_path = pending[0]
                        request = json.loads(request_path.read_text())
                        prompt = (BASE / request['prompt_path']).resolve()
                        if not prompt.is_relative_to((BASE / name).resolve()):
                            raise RuntimeError('Followup prompt escaped its assigned job directory')
                        if not record['thread_id']:
                            raise RuntimeError('Cannot resume a failed start without a thread ID')
                        if launch(name, prompt, record['turn'] + 1, record['thread_id']):
                            request_path.rename(request_path.with_suffix('.consumed'))
            snapshot()
            if (BASE / 'STOP').exists():
                break
            time.sleep(2)
    finally:
        stop_owned()
        snapshot()
        write(BASE / 'runner-exit.json', {'end_unix': time.time(), 'deadline_unix': DEADLINE})


if __name__ == '__main__':
    main()

