    def _close_transport(self):
        # Reject requests immediately, but only completed teardown is a no-op.
        if getattr(self, '_transport_closed', False):
            return
        self.closed = True
        if self.process is None:
            self._transport_closed = True
            return
        try:
            if self._broken:
                # Do this before closing buffered stdin: its pending flush
                # could otherwise block behind an unread response tail.
                self.process.kill()
            try:
